package io.xeros.solo;
import io.xeros.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import io.xeros.content.commands.all.Charge;import java.util.Arrays;
public class Charge74Check{
 static void ok(boolean b,String m){if(!b)throw new AssertionError(m);System.out.println("PASS "+m);}
 public static void main(String[] a){try{Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");Server.startServerless();Player p=BossesPlayableCheck.actor();p.setLoginName("qacharge74");p.getItems().setEquipment(27275,1,3,false);p.getEquipmentChargeLedger().set("e3",0);int[] items=p.playerItems.clone(),qty=p.playerItemsN.clone();new Charge().execute(p,"charge","shadow max");ok(p.getEquipmentChargeLedger().equipped()==20000,"Max cheat fills Shadow to 20000");ok(Arrays.equals(items,p.playerItems)&&Arrays.equals(qty,p.playerItemsN),"Max cheat consumes no inventory materials");p.getEquipmentChargeLedger().consume();ok(p.getEquipmentChargeLedger().equipped()==19999,"Combat consumption remains enabled");ok(PlayerSave.saveGameInstant(p),"Save charged weapon");Player q=BossesPlayableCheck.actor();ok(PlayerSave.loadGame(q,"qacharge74","IsolatedAudit",true).toString().equals("SUCCESS"),"Reload saved account");ok(q.getEquipmentChargeLedger().equipped()==19999,"Charges persist on real save/reload");System.setProperty("solo.mode","false");q.getEquipmentChargeLedger().set("e3",12);new Charge().execute(q,"charge","shadow max");ok(q.getEquipmentChargeLedger().equipped()==12,"Cheat is restricted to solo mode");System.out.println("CHARGE74_PASS");System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
